import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent,
  type VideoHTMLAttributes,
} from "react";
import { cn } from "@/lib/utils";
import { useShape } from "@/lib/shape-context";

interface SimplePlayerProps extends Omit<
  VideoHTMLAttributes<HTMLVideoElement>,
  "className" | "controls" | "src"
> {
  /** Video URL. The source is attached lazily as the player approaches the viewport. */
  src: string;
  /** CSS aspect-ratio value used by the player shell. */
  aspectRatio?: CSSProperties["aspectRatio"];
  /** Root player classes. */
  className?: string;
  /** Classes applied to the video element. */
  videoClassName?: string;
  /** Show volume, Picture-in-Picture, and fullscreen controls. */
  controls?: boolean;
  /** Show elapsed or remaining time above the progress rail. */
  showTime?: boolean;
  /** Toggle playback by clicking the non-control video surface. */
  pauseOnOverlayClick?: boolean;
  /** IntersectionObserver root margin used for lazy source loading. */
  preloadMargin?: string;
  /** Initial volume from 0 to 1. */
  defaultVolume?: number;
  /** Accessible name for the player group. */
  label?: string;
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

function formatTime(seconds: number) {
  if (!Number.isFinite(seconds) || seconds < 0) return "0:00";

  const rounded = Math.floor(seconds);
  const hours = Math.floor(rounded / 3600);
  const minutes = Math.floor((rounded % 3600) / 60);
  const remainder = rounded % 60;

  if (hours > 0) {
    return `${hours}:${String(minutes).padStart(2, "0")}:${String(remainder).padStart(2, "0")}`;
  }

  return `${minutes}:${String(remainder).padStart(2, "0")}`;
}

function PlayIcon({ playing }: { playing: boolean }) {
  return (
    <span className="relative grid size-[54px] place-items-center" aria-hidden="true">
      <svg
        viewBox="0 0 18 20"
        className={cn(
          "col-start-1 row-start-1 h-[60px] w-[54px] overflow-visible transition-[opacity,transform] duration-200 motion-reduce:transition-none",
          playing
            ? "translate-x-1 rotate-[70deg] scale-75 opacity-0"
            : "translate-x-1 scale-100 opacity-100",
        )}
      >
        <path
          d="M3 3.5 15 10 3 16.5Z"
          fill="currentColor"
          stroke="currentColor"
          strokeWidth="1.5"
          strokeLinejoin="round"
        />
      </svg>
      <svg
        viewBox="0 0 18 20"
        className={cn(
          "col-start-1 row-start-1 h-[60px] w-[54px] overflow-visible transition-[opacity,transform] duration-200 motion-reduce:transition-none",
          playing ? "scale-100 opacity-100" : "-rotate-[70deg] scale-75 opacity-0",
        )}
      >
        <rect x="3" y="3" width="5" height="14" rx="1.5" fill="currentColor" />
        <rect x="10" y="3" width="5" height="14" rx="1.5" fill="currentColor" />
      </svg>
    </span>
  );
}

function VolumeIcon({ muted }: { muted: boolean }) {
  return muted ? (
    <svg viewBox="0 0 20 20" className="size-5" aria-hidden="true">
      <path d="M3 17 17 3" fill="none" stroke="currentColor" strokeLinecap="round" />
      <path
        d="M12 2.4c1.24-.9 3-.02 3 1.54v.94l-2 2V4.14L8.64 7.77A1 1 0 0 1 8 8H5a1 1 0 0 0-1 1v2a1 1 0 0 0 1 1h2.88l-2 2H5a3 3 0 0 1-3-3V9a3 3 0 0 1 3-3h2.64l4.24-3.54Z"
        fill="currentColor"
      />
    </svg>
  ) : (
    <svg viewBox="0 0 20 20" className="size-5" aria-hidden="true">
      <path
        d="M8 7H5a2 2 0 0 0-2 2v2a2 2 0 0 0 2 2h3l4.52 3.77A.9.9 0 0 0 14 16.08V3.92a.9.9 0 0 0-1.48-.69L8 7Z"
        fill="none"
        stroke="currentColor"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <path d="M17.4 8.6a2 2 0 0 1 0 2.8" fill="none" stroke="currentColor" strokeLinecap="round" />
    </svg>
  );
}

function PictureInPictureIcon() {
  return (
    <svg viewBox="0 0 20 20" className="size-5" aria-hidden="true">
      <path
        d="M5.5 13A2.5 2.5 0 0 1 3 10.5v-5A2.5 2.5 0 0 1 5.5 3h7A2.5 2.5 0 0 1 15 5.5V8"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <rect x="9" y="12" width="8" height="5" rx="1.5" fill="currentColor" />
      <path
        d="m8 8-2-2m3 0v3H6"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function FullscreenIcon({ active }: { active: boolean }) {
  return (
    <svg viewBox="0 0 20 20" className="size-5" aria-hidden="true">
      {active ? (
        <>
          <path d="M16 12.5h-3.5V16M12 12l4 4" fill="none" stroke="currentColor" />
          <path d="M4 7.5h3.5V4M8 8 4 4" fill="none" stroke="currentColor" />
        </>
      ) : (
        <>
          <path d="M12.5 16H16v-3.5M16 16l-4-4" fill="none" stroke="currentColor" />
          <path d="M7.5 4H4v3.5M4 4l4 4" fill="none" stroke="currentColor" />
        </>
      )}
    </svg>
  );
}

const controlButtonClasses =
  "grid size-7 shrink-0 place-items-center rounded-[4px] text-white/80 outline-none transition-[background-color,color,transform] duration-150 hover:bg-white/15 hover:text-white focus-visible:bg-white/15 focus-visible:text-white active:scale-95 motion-reduce:transition-none";

export const SimplePlayer = forwardRef<HTMLVideoElement, SimplePlayerProps>(function SimplePlayer(
  {
    src,
    aspectRatio = "16 / 9",
    className,
    videoClassName,
    controls = false,
    showTime = false,
    pauseOnOverlayClick = false,
    preloadMargin = "360px 0px",
    defaultVolume = 1,
    label = "Video player",
    autoPlay = true,
    loop = true,
    muted = true,
    playsInline = true,
    preload = "metadata",
    poster,
    onCanPlay,
    onDurationChange,
    onEnded,
    onError,
    onLoadedData,
    onLoadedMetadata,
    onPause,
    onPlay,
    onPlaying,
    onProgress,
    onTimeUpdate,
    onVolumeChange,
    onWaiting,
    ...videoProps
  },
  forwardedRef,
) {
  const shape = useShape();
  const rootRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const hideTimerRef = useRef<number | null>(null);
  const [shouldLoad, setShouldLoad] = useState(false);
  const [hasVisibleFrame, setHasVisibleFrame] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isBuffering, setIsBuffering] = useState(true);
  const [hasError, setHasError] = useState(false);
  const [controlsVisible, setControlsVisible] = useState(true);
  const [duration, setDuration] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [bufferedPercent, setBufferedPercent] = useState(0);
  const [hoverPercent, setHoverPercent] = useState<number | null>(null);
  const [volume, setVolume] = useState(clamp(defaultVolume, 0, 1));
  const [isMuted, setIsMuted] = useState(muted);
  const [isPictureInPicture, setIsPictureInPicture] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [pictureInPictureSupported, setPictureInPictureSupported] = useState(false);
  const [fullscreenSupported, setFullscreenSupported] = useState(false);
  const [timeMode, setTimeMode] = useState<"elapsed" | "remaining">("elapsed");

  useImperativeHandle(forwardedRef, () => videoRef.current as HTMLVideoElement, []);

  const clearHideTimer = useCallback(() => {
    if (hideTimerRef.current === null) return;
    window.clearTimeout(hideTimerRef.current);
    hideTimerRef.current = null;
  }, []);

  const scheduleControlsHide = useCallback(() => {
    clearHideTimer();
    if (!isPlaying) return;
    hideTimerRef.current = window.setTimeout(() => {
      setControlsVisible(false);
      setHoverPercent(null);
    }, 1600);
  }, [clearHideTimer, isPlaying]);

  const revealControls = useCallback(() => {
    setControlsVisible(true);
    scheduleControlsHide();
  }, [scheduleControlsHide]);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;

    setShouldLoad(false);
    setHasVisibleFrame(false);
    setHasError(false);
    setIsPlaying(false);
    setIsBuffering(true);
    setDuration(0);
    setCurrentTime(0);
    setBufferedPercent(0);

    if (!("IntersectionObserver" in window)) {
      setShouldLoad(true);
      return;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        if (!entries.some((entry) => entry.isIntersecting)) return;
        setShouldLoad(true);
        observer.disconnect();
      },
      { rootMargin: preloadMargin },
    );

    observer.observe(root);
    return () => observer.disconnect();
  }, [preloadMargin, src]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    video.volume = clamp(defaultVolume, 0, 1);
    video.muted = muted;
    setVolume(video.volume);
    setIsMuted(video.muted);
  }, [defaultVolume, muted]);

  useEffect(() => {
    if (isPlaying) {
      revealControls();
    } else {
      clearHideTimer();
      setControlsVisible(true);
    }
    return clearHideTimer;
  }, [clearHideTimer, isPlaying, revealControls]);

  useEffect(() => {
    const video = videoRef.current;
    const root = rootRef.current;
    if (!video || !root) return;

    const syncPictureInPicture = () => {
      setIsPictureInPicture(document.pictureInPictureElement === video);
    };
    const syncFullscreen = () => {
      setIsFullscreen(document.fullscreenElement === root);
    };

    setPictureInPictureSupported(
      Boolean(document.pictureInPictureEnabled && "requestPictureInPicture" in video),
    );
    setFullscreenSupported(Boolean(document.fullscreenEnabled && "requestFullscreen" in root));
    video.addEventListener("enterpictureinpicture", syncPictureInPicture);
    video.addEventListener("leavepictureinpicture", syncPictureInPicture);
    document.addEventListener("fullscreenchange", syncFullscreen);

    return () => {
      video.removeEventListener("enterpictureinpicture", syncPictureInPicture);
      video.removeEventListener("leavepictureinpicture", syncPictureInPicture);
      document.removeEventListener("fullscreenchange", syncFullscreen);
    };
  }, []);

  const syncBuffered = useCallback(() => {
    const video = videoRef.current;
    if (!video || !Number.isFinite(video.duration) || video.duration <= 0) {
      setBufferedPercent(0);
      return;
    }

    const end = video.buffered.length > 0 ? video.buffered.end(video.buffered.length - 1) : 0;
    setBufferedPercent(clamp((end / video.duration) * 100, 0, 100));
  }, []);

  const togglePlayback = useCallback(async () => {
    const video = videoRef.current;
    if (!video || hasError) return;

    try {
      if (video.paused || video.ended) {
        await video.play();
      } else {
        video.pause();
      }
    } catch {
      setIsPlaying(false);
      setControlsVisible(true);
    }
  }, [hasError]);

  const seekToPercent = useCallback(
    (percent: number) => {
      const video = videoRef.current;
      if (!video || duration <= 0) return;
      const nextTime = (clamp(percent, 0, 100) / 100) * duration;
      video.currentTime = nextTime;
      setCurrentTime(nextTime);
    },
    [duration],
  );

  const handlePlayerKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.target !== event.currentTarget) return;
    if (![" ", "Enter", "k", "K"].includes(event.key)) return;
    event.preventDefault();
    void togglePlayback();
  };

  const handleProgressPointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    const percent = clamp(((event.clientX - rect.left) / rect.width) * 100, 0, 100);
    setHoverPercent(percent);
  };

  const toggleMute = () => {
    const video = videoRef.current;
    if (!video) return;
    video.muted = !video.muted;
    setIsMuted(video.muted);
    revealControls();
  };

  const updateVolume = (nextVolume: number) => {
    const video = videoRef.current;
    if (!video) return;
    const normalized = clamp(nextVolume, 0, 1);
    video.volume = normalized;
    video.muted = normalized === 0;
    setVolume(normalized);
    setIsMuted(video.muted);
    revealControls();
  };

  const togglePictureInPicture = async () => {
    const video = videoRef.current;
    if (!video || !document.pictureInPictureEnabled || !video.requestPictureInPicture) return;

    try {
      if (document.pictureInPictureElement === video) {
        await document.exitPictureInPicture();
      } else {
        await video.requestPictureInPicture();
      }
    } catch {
      // Browsers can reject Picture-in-Picture without media readiness or user activation.
    }
  };

  const toggleFullscreen = async () => {
    const root = rootRef.current;
    if (!root || !document.fullscreenEnabled) return;

    try {
      if (document.fullscreenElement === root) {
        await document.exitFullscreen();
      } else {
        await root.requestFullscreen();
      }
    } catch {
      // Browsers can reject fullscreen without user activation.
    }
  };

  const progressPercent = duration > 0 ? clamp((currentTime / duration) * 100, 0, 100) : 0;
  const displayTime =
    timeMode === "elapsed"
      ? formatTime(currentTime)
      : `-${formatTime(Math.max(0, duration - currentTime))}`;

  return (
    <div
      ref={rootRef}
      role="group"
      aria-label={label}
      aria-busy={isBuffering}
      tabIndex={0}
      data-simple-player=""
      data-state={hasError ? "error" : isPlaying ? "playing" : "paused"}
      className={cn(
        "group/simple-player relative isolate block w-full overflow-hidden bg-[#1e1e1e] text-white shadow-sm outline-none ring-offset-background focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
        shape.container,
        className,
      )}
      style={{ aspectRatio }}
      onKeyDown={handlePlayerKeyDown}
      onPointerEnter={revealControls}
      onPointerMove={revealControls}
      onPointerLeave={scheduleControlsHide}
      onFocusCapture={revealControls}
      onBlurCapture={(event) => {
        if (event.relatedTarget && event.currentTarget.contains(event.relatedTarget as Node)) {
          return;
        }
        scheduleControlsHide();
      }}
    >
      <video
        {...videoProps}
        ref={videoRef}
        src={shouldLoad ? src : undefined}
        poster={poster}
        autoPlay={autoPlay}
        loop={loop}
        muted={isMuted}
        playsInline={playsInline}
        preload={preload}
        controls={false}
        controlsList="nodownload nofullscreen noremoteplayback"
        disablePictureInPicture={!controls}
        disableRemotePlayback
        className={cn(
          "pointer-events-none absolute inset-0 block size-full select-none object-cover transition-opacity duration-200 motion-reduce:transition-none",
          hasVisibleFrame ? "opacity-100" : "opacity-0",
          videoClassName,
        )}
        onCanPlay={(event) => {
          setIsBuffering(false);
          onCanPlay?.(event);
        }}
        onDurationChange={(event) => {
          setDuration(
            Number.isFinite(event.currentTarget.duration) ? event.currentTarget.duration : 0,
          );
          onDurationChange?.(event);
        }}
        onEnded={(event) => {
          setIsPlaying(false);
          onEnded?.(event);
        }}
        onError={(event) => {
          setHasError(true);
          setIsBuffering(false);
          setIsPlaying(false);
          onError?.(event);
        }}
        onLoadedData={(event) => {
          setHasVisibleFrame(true);
          setIsBuffering(false);
          onLoadedData?.(event);
        }}
        onLoadedMetadata={(event) => {
          setDuration(
            Number.isFinite(event.currentTarget.duration) ? event.currentTarget.duration : 0,
          );
          syncBuffered();
          onLoadedMetadata?.(event);
        }}
        onPause={(event) => {
          setIsPlaying(false);
          onPause?.(event);
        }}
        onPlay={(event) => {
          setIsPlaying(true);
          setHasError(false);
          onPlay?.(event);
        }}
        onPlaying={(event) => {
          setIsPlaying(true);
          setIsBuffering(false);
          setHasVisibleFrame(true);
          onPlaying?.(event);
        }}
        onProgress={(event) => {
          syncBuffered();
          onProgress?.(event);
        }}
        onTimeUpdate={(event) => {
          setCurrentTime(event.currentTarget.currentTime);
          onTimeUpdate?.(event);
        }}
        onVolumeChange={(event) => {
          setVolume(event.currentTarget.volume);
          setIsMuted(event.currentTarget.muted);
          onVolumeChange?.(event);
        }}
        onWaiting={(event) => {
          setIsBuffering(true);
          onWaiting?.(event);
        }}
      />

      <div
        role="presentation"
        aria-hidden="true"
        className={cn(
          "absolute inset-0 z-10 cursor-default bg-black/40 backdrop-blur-[2px] outline-none transition-opacity duration-300 motion-reduce:transition-none",
          controlsVisible && !hasError ? "opacity-100" : "pointer-events-none opacity-0",
          pauseOnOverlayClick && "cursor-pointer",
        )}
        onPointerUp={() => {
          if (pauseOnOverlayClick) void togglePlayback();
        }}
      />

      <button
        type="button"
        aria-label={isPlaying ? "Pause video" : "Play video"}
        className={cn(
          "absolute left-1/2 top-1/2 z-20 grid size-[60px] -translate-x-1/2 -translate-y-1/2 place-items-center text-white outline-none transition-[opacity,transform] duration-300 focus-visible:ring-2 focus-visible:ring-white/80 motion-reduce:transition-none",
          controlsVisible && !isBuffering && !hasError
            ? "scale-100 opacity-100"
            : "pointer-events-none scale-95 opacity-0",
        )}
        onClick={() => void togglePlayback()}
      >
        <PlayIcon playing={isPlaying} />
      </button>

      {isBuffering && !hasError ? (
        <div
          role="status"
          aria-label="Loading video"
          className="absolute left-1/2 top-1/2 z-20 h-1 w-[min(148px,70%)] -translate-x-1/2 -translate-y-1/2 overflow-hidden rounded-full bg-white/10"
        >
          <span className="block h-full w-1/2 animate-pulse rounded-full bg-white/45 motion-reduce:animate-none" />
        </div>
      ) : null}

      {hasError ? (
        <div
          role="alert"
          className="absolute inset-0 z-20 grid place-items-center bg-black/55 px-6 text-center text-[13px] text-white/75"
        >
          Video unavailable
        </div>
      ) : null}

      {!hasError ? (
        <div
          className={cn(
            "absolute inset-x-4 bottom-2 z-30 transition-[opacity,transform] duration-300 motion-reduce:transition-none",
            controlsVisible
              ? "translate-y-0 opacity-100"
              : "pointer-events-none translate-y-1 opacity-0",
          )}
        >
          {showTime && controlsVisible ? (
            <button
              type="button"
              aria-label="Toggle elapsed and remaining time"
              className="absolute bottom-8 left-0 rounded-[5px] border border-white/10 bg-white/15 px-2 py-1 font-mono text-[11px] tabular-nums text-white/90 shadow-sm backdrop-blur-md outline-none hover:bg-white/20 focus-visible:ring-2 focus-visible:ring-white/80"
              onClick={() =>
                setTimeMode((current) => (current === "elapsed" ? "remaining" : "elapsed"))
              }
            >
              {displayTime}
            </button>
          ) : null}

          {controls ? (
            <div className="absolute bottom-8 right-0 flex h-8 items-center gap-0.5 rounded-[6px] border border-white/10 bg-white/15 p-0.5 shadow-sm backdrop-blur-md">
              <div className="group/volume flex items-center">
                <label
                  className="grid w-0 overflow-hidden rounded-full opacity-0 transition-[width,opacity] duration-200 group-hover/volume:w-16 group-hover/volume:opacity-100 group-focus-within/volume:w-16 group-focus-within/volume:opacity-100 has-[input:focus-visible]:ring-2 has-[input:focus-visible]:ring-white/80 has-[input:focus-visible]:ring-offset-2 has-[input:focus-visible]:ring-offset-transparent motion-reduce:transition-none"
                  aria-label="Volume"
                >
                  <input
                    type="range"
                    min="0"
                    max="1"
                    step="0.01"
                    value={isMuted ? 0 : volume}
                    aria-label="Volume"
                    aria-valuetext={`${Math.round((isMuted ? 0 : volume) * 100)}%`}
                    className={cn(
                      "mx-2 h-5 w-12 appearance-none rounded-full border-0 bg-transparent p-0 shadow-none outline-none cursor-pointer",
                      "[&::-webkit-slider-runnable-track]:h-1 [&::-webkit-slider-runnable-track]:rounded-full [&::-webkit-slider-runnable-track]:border-0 [&::-webkit-slider-runnable-track]:bg-white/30",
                      "[&::-webkit-slider-thumb]:-mt-1 [&::-webkit-slider-thumb]:size-3 [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:border-0 [&::-webkit-slider-thumb]:bg-white [&::-webkit-slider-thumb]:shadow-none",
                      "[&::-moz-range-track]:h-1 [&::-moz-range-track]:rounded-full [&::-moz-range-track]:border-0 [&::-moz-range-track]:bg-white/30 [&::-moz-range-progress]:h-1 [&::-moz-range-progress]:rounded-full [&::-moz-range-progress]:bg-white",
                      "[&::-moz-range-thumb]:size-3 [&::-moz-range-thumb]:appearance-none [&::-moz-range-thumb]:rounded-full [&::-moz-range-thumb]:border-0 [&::-moz-range-thumb]:bg-white [&::-moz-range-thumb]:shadow-none",
                    )}
                    onChange={(event) => updateVolume(Number(event.currentTarget.value))}
                  />
                </label>
                <button
                  type="button"
                  aria-label={isMuted ? "Unmute video" : "Mute video"}
                  className={controlButtonClasses}
                  onClick={toggleMute}
                >
                  <VolumeIcon muted={isMuted || volume === 0} />
                </button>
              </div>

              {pictureInPictureSupported ? (
                <button
                  type="button"
                  aria-label={
                    isPictureInPicture ? "Exit picture in picture" : "Enter picture in picture"
                  }
                  className={controlButtonClasses}
                  onClick={() => void togglePictureInPicture()}
                >
                  <PictureInPictureIcon />
                </button>
              ) : null}

              {fullscreenSupported ? (
                <button
                  type="button"
                  aria-label={isFullscreen ? "Exit fullscreen" : "Enter fullscreen"}
                  className={controlButtonClasses}
                  onClick={() => void toggleFullscreen()}
                >
                  <FullscreenIcon active={isFullscreen} />
                </button>
              ) : null}
            </div>
          ) : null}

          <div
            className="group/progress relative h-7 w-full touch-none rounded-sm has-[input:focus-visible]:ring-2 has-[input:focus-visible]:ring-inset has-[input:focus-visible]:ring-white/80"
            onPointerMove={handleProgressPointerMove}
            onPointerLeave={() => setHoverPercent(null)}
          >
            {hoverPercent !== null && showTime && !controls ? (
              <span
                className="pointer-events-none absolute bottom-6 -translate-x-1/2 rounded-[5px] border border-white/10 bg-white/15 px-1.5 py-0.5 font-mono text-[10px] tabular-nums text-white/90 backdrop-blur-md"
                style={{ left: `${hoverPercent}%` }}
              >
                {formatTime((hoverPercent / 100) * duration)}
              </span>
            ) : null}
            <span className="absolute inset-x-0 bottom-1.5 h-2 overflow-hidden rounded-full bg-white/[0.12] backdrop-blur-md transition-[height] duration-150 group-hover/progress:h-3.5 group-focus-within/progress:h-3.5 motion-reduce:transition-none">
              <span
                className="absolute inset-y-0 left-0 bg-white/15"
                style={{ width: `${bufferedPercent}%` }}
              />
              {hoverPercent !== null ? (
                <span
                  className="absolute inset-y-0 left-0 bg-white/15"
                  style={{ width: `${hoverPercent}%` }}
                />
              ) : null}
              <span
                className="absolute inset-y-0 left-0 rounded-full bg-white"
                style={{ width: `${progressPercent}%` }}
              />
            </span>
            <input
              type="range"
              min="0"
              max="100"
              step="0.05"
              value={progressPercent}
              aria-label="Video progress"
              aria-valuetext={`${formatTime(currentTime)} of ${formatTime(duration)}`}
              className="absolute inset-0 size-full cursor-pointer opacity-0 outline-none"
              onPointerDown={clearHideTimer}
              onPointerUp={scheduleControlsHide}
              onChange={(event) => seekToPercent(Number(event.currentTarget.value))}
            />
          </div>
        </div>
      ) : null}
    </div>
  );
});

export type { SimplePlayerProps };
